import { Box, TextField, Typography, Button, FormGroup, FormControlLabel, Checkbox, CircularProgress, useMediaQuery } from "@mui/material";
import axios from "axios";
import { useState } from "react";
import config from "../config";
import { useNavigate, Link } from "react-router-dom";

export default function Login() {
    const navigate = useNavigate();
    const [loading, setLoading] = useState(false);
    const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");
    const [autoLogin, setAutoLogin] = useState(false);
    const [emailError, setEmailError] = useState("");
    const [passwordError, setPasswordError] = useState("");
    const [loginError, setLoginError] = useState("");

    const isSmallScreen = useMediaQuery('(max-width:600px)');

    const validateEmail = () => {
        if (email.trim() === "") {
            setEmailError("メールアドレスを入力してください");
        } else if (!email.includes("@")) {
            setEmailError("無効なメールアドレスです");
        } else {
            setEmailError("");
        }
    };

    const handleEmailChange = (event) => {
        setEmail(event.target.value);

        if (emailError) {
            setEmailError("");
        }
    };

    const validatePassword = () => {
        if (password.trim() === "") {
            setPasswordError("パスワードを入力してください");
        } else if (password.length <= 5) {
            setPasswordError("パスワードは6文字以上で入力してください");
        } else if (!/[a-zA-Z]/.test(password) || !/[0-9]/.test(password)) {
            setPasswordError("パスワードには英字と数字の両方を含めてください");
        } else {
            setPasswordError("");
        }
    };

    const handlePasswordChange = (event) => {
        setPassword(event.target.value);

        if (passwordError) {
            setPasswordError("");
        }
    };

    const handleCheckBox = () => {
        setAutoLogin(!autoLogin);
    };

    const handleLogin = async () => {
        if (email !== "" && password !== "" && emailError === "" && passwordError === "") {
            setLoading(true);

            const response = await axios.post(`${config.serverURL}/api/login`, { email: email, password: password, autoLogin: autoLogin });
            const data = response.data;

            if (data.success) {
                navigate("/home");
            } else {
                setLoginError(data.error);
            }

            setLoading(false);
        } else {
            validateEmail();
            validatePassword();
        }
    };

    return (
        <Box
            display="flex"
            justifyContent="center"
            alignItems="center"
            height="100vh"
            width="100vw"
            margin="0"
            padding="0"
            position="fixed"
            top="0"
            left="0"
            bgcolor="whitesmoke"
        >
            {isSmallScreen ? (
                <Box textAlign="center">
                    <Typography fontWeight="bold" fontSize="25px" mb="30px" color="black">
                        VSpaceへログイン
                    </Typography>
                    <Typography>
                        アカウントをお持ちでない方は
                        <Link to="/signup" style={{ color: "blue" }}>
                            サインアップ
                        </Link>
                    </Typography>
                </Box>
            ) : (
                <Box
                    style={isSmallScreen ? {
                        backgroundColor: "white",
                        borderRadius: "8px",
                        padding: "40px",
                        boxShadow: "0 0 10px rgba(0, 0, 0, 0.2)",
                        textAlign: "center",
                        width: "90%",
                        maxWidth: "400px",
                        backdropFilter: "blur(10px)",
                        WebkitBackdropFilter: "blur(10px)",
                    } : {
                        
                    }}
                >
                    <Typography fontWeight="bold" fontSize="25px" mb="30px" color="black">
                        VSpaceへログイン
                    </Typography>
                    <TextField
                        id="email"
                        label="メールアドレス"
                        variant="outlined"
                        fullWidth
                        style={{ marginBottom: "25px" }}
                        value={email}
                        onBlur={validateEmail}
                        error={Boolean(emailError)}
                        helperText={emailError}
                        onChange={handleEmailChange}
                    />
                    <TextField
                        id="password"
                        label="パスワード"
                        variant="outlined"
                        type="password"
                        fullWidth
                        style={{ marginBottom: "15px" }}
                        value={password}
                        onBlur={validatePassword}
                        error={Boolean(passwordError)}
                        helperText={passwordError}
                        onChange={handlePasswordChange}
                    />
                    <FormGroup style={{ marginBottom: "15px" }}>
                        <FormControlLabel
                            control={
                                <Checkbox
                                    sx={{
                                        color: "black",
                                        "&.Mui-checked": {
                                            color: "black"
                                        },
                                    }}
                                    onClick={handleCheckBox}
                                />
                            }
                            label="自動ログイン"
                        />
                    </FormGroup>
                    <Box mb="20px">
                        <Button
                            variant="contained"
                            fullWidth
                            disabled={loading}
                            style={{ padding: "15px", backgroundColor: "black", color: "white" }}
                            onClick={handleLogin}
                        >
                            ログイン
                            {loading && (
                                <Box position="absolute" display="flex" justifyContent="center" alignItems="center" width="50%" height="50%" bgcolor="black">
                                    <CircularProgress size="20px" style={{ color: "white" }} />
                                </Box>
                            )}
                        </Button>
                    </Box>
                    <Typography>
                        アカウントをお持ちでない方は
                        <Link to="/signup" style={{ color: "blue" }}>
                            サインアップ
                        </Link>
                    </Typography>
                </Box>
            )}
        </Box>
    );
}
